class Solver:
 def solve(self,problem,**kwargs):
  k,n,p,a=(problem[x] for x in ('key','nonce','plaintext','associated_data'))
  out=bytes(len(p)); tag=bytes(16)
  _lib.fast(_P(k),_P(n),_P(p),len(p),_P(a),len(a),_P(out),_P(tag))
